  const d=frame.contentDocument,w=d.defaultView,panel=document.createElement('div'),heading=document.createElement('strong'),search=document.createElement('input'),list=document.createElement('div'),note=document.createElement('p'),close=document.createElement('button'),outline=document.createElement('div'),listeners=[];
  panel.className='prototype-target-picker';panel.setAttribute('popover','manual');panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Choose scroll destination');heading.textContent='Choose destination';search.type='search';search.placeholder='Find a layer…';search.setAttribute('aria-label','Find scroll destination');close.textContent='Cancel';close.type='button';close.className='control-button';note.textContent='Click a layer on the page, or choose from the list. Escape cancels.';note.setAttribute('role','status');outline.className='prototype-target-outline';outline.setAttribute('aria-hidden','true');
