  function valid(el){if(!el?.isConnected||!el.getClientRects().length||['script','style','link','meta','title'].includes(el.localName))return false;const id=el.getAttribute('data-rt');return id&&sourceCounts.get(id)===1&&(!el.id||idCounts.get(el.id)===1);}

  function highlight(el){if(!el){outline.hidden=true;return;}const rect=el.getBoundingClientRect(),frameRect=frame.getBoundingClientRect(),sx=frameRect.width/frame.clientWidth,sy=frameRect.height/frame.clientHeight;outline.hidden=false;Object.assign(outline.style,{left:frameRect.left+rect.left*sx+'px',top:frameRect.top+rect.top*sy+'px',width:rect.width*sx+'px',height:rect.height*sy+'px'});}
